#!/usr/bin/env bash
# Self-contained CSS + ассеты для run-finale/bg2-page-round (prod parity финала ★ BG-2, bash-only).
set -euo pipefail

ROUND="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
LAB="$(cd "$ROUND/../.." && pwd)"
BG="$LAB/board-game"
OUT="$ROUND/lab-base.css"
SOURCES=("$BG/styles.css" "$BG/logic-round/styles.css" "$BG/hybrid-round/styles.css" "$BG/screens-round/styles.css")

{
  cat <<'HDR'
/* Auto-generated by sync-lab.sh - do not edit by hand */
/* Round: run-finale/bg2-page-round */
/* Sources: board-game/styles.css (tokens ADR-014) + logic-round + hybrid-round + screens-round (★ BG-2) */

HDR
  for src in "${SOURCES[@]}"; do
    if [[ ! -f "$src" ]]; then
      echo "sync-lab.sh: missing source: $src" >&2
      exit 1
    fi
    cat "$src"
    printf '\n'
  done
} > "$OUT"

mkdir -p "$ROUND/assets"
cp "$LAB/run-finale/assets/student-mascot-cup-dash.png" "$ROUND/assets/"
cp "$LAB/run-finale/assets/student-mascot-dash.png" "$ROUND/assets/"
cp "$LAB/run-finale/assets/entrepreneur-mascot-dash.png" "$ROUND/assets/"

echo "OK: $OUT"
